namespace OpenTPW.UI.Original;

/// <summary>
/// Register of every UI value or rule that is not taken from original data or hard evidence
/// (docs/UI.md "Approximation register"). Each site carries a matching
/// <c>// [APPROX:UI-NNN]</c> comment; <see cref="LogOnce"/> reports them at startup.
/// </summary>
public static class UiApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("UI-003", "selected-mesh endpoint fitting is retained, but state geometry still uses the root-pose shortcut; full ancestor composition, general state traversal and control rotation remain unimplemented", "corpus-external hierarchy/rotation validation and rendered comparison"),
		("UI-004", "UI model triangles drawn back to front by Z, grouped per texture; the original's display object divides its depth buffer into a UI range in front of a linear and a log range (the dump 0x5833c0 prints [+0x48] begin, [+0x4c] ui end / linear begin, [+0x50] linear end / log begin, [+0x54] log end; the buffer itself is enabled or not, strings 0x768988 and 0x768958), which suggests depth-tested rather than sorted UI parts, not shown for the UI model draw; the device init 0x573080 sets ZENABLE 1, ZFUNC LESSEQUAL (4) and ZWRITEENABLE 1 when the display object's flag +0x88 bit 0x10 is set and ZENABLE and ZWRITEENABLE 0 otherwise, so a UI part is depth-tested when the buffer is on, but the UI draw's own state and order are not found", "the UI model draw call (which per-draw depth state and which order it submits) and the writer of the four range floats +0x48..+0x54"),
		("UI-006", "text colours: window titles and the lobby island name yellow, the object windows' labels and values white, the pause menu's lines cyan (white while focused), green values elsewhere, grey disabled, shadow and backdrop colours (the video's 720p chroma is good to about +-15 per channel); the original gives each text control an RGBA colour (0x65c5d5 → renderer +0x48, kept as ARGB at +0x78, 0x48fd07; the sprite draw 0x58a010 takes it as the diffuse colour of the control's quads, 0x58a019) and renders its glyphs white (0x48fa96) unless the control keeps the font's own colours (+0xdd); the values traced are the options labels' (0,0,0,255) (0x4a441e, UI-037), the buy list rows' (255,255,255,255) (0x4ad340), the pause menu lines' (0,175,190,255) (0x48b2b9) and the shared title colour (234,239,102,255) (0x492d20, fifteen window builders), with the lobby island name's second line (252,232,7,255) (0x4b8604) and a list row control that turns (140,0,60) on message 0x403 with a negative argument (0x4a0710); the other 0x65c5d5 calls (134 sites in all; by an instruction scan: about 36 with white (255,255,255,255), 31 with black (0,0,0,255) such as the runs 0x49ada6-0x49b385 and 0x4a53a2-0x4a5d26, 7 with red (255,0,0,255) at 0x49ff69, 0x4a002f, 0x4a6273 and 0x4b2e93-0x4b31f7, 5 with (224,86,86,255) at 0x4aa82d-0x4aac70, and about 45 that pass the colour from registers or tables) are not yet assigned to screens", "which screen each remaining 0x65c5d5 call colours (values, disabled states, costs) and the backdrop colours"),
		("UI-007", "one-pixel (×UI scale) drop shadow under UI text; the original's control text renderer (0x48f830) lays each string out and draws it once (one 0x6ae0f0 call into the control's bitmap), so its controls have no drop shadow; the whole glyph layout and draw library has one draw entry, 0x6ae0f0, whose only caller is the text box routine 0x492750 (three callers, each calling it once: the label and list text of 0x4a84c0 through 0x492c40, 0x480810 through 0x47fcd0 and 0x480460, 0x480570 through 0x47fe90; 0x6ae1c0 is the measure entry used by 0x4929f0), no offset or second pass exists there, and the BF4 glyphs carry only 0-15 coverage samples (docs/BF4-FONTS.md), so no shadow is baked into the font art; the control's attribute byte +0xdb is only ever written (the constructors 0x48f703, 0x48fe3d, 0x490091 and the attribute setter 0x48fcab; no read form of it exists in tp.exe's code by a byte scan), so it is no shadow flag; the capture's apparent shadow is not explained, and the vtable-reached control renderer 0x48f830 and the sprite blit of its bitmap (0x48f410) are not shown to add one; the control draws into its own bitmap in the display mode's pixel format (0x4925d0 copies the 32-byte mode record at 0x8bd558, bit depth and channel masks, into the surface description; 0x48fb64 clears the bitmap to zero first), through the blended one-colour glyph blitters: the 5-5-5 one (0x6b0760) blends each channel as dst + ((src - dst) * coverage) / 15 in signed 5-bit arithmetic and keeps the destination's alpha bit, so white text on the cleared bitmap yields grey levels with alpha bit 0 and the coverage reaches the screen only through the sprite draw's state; the 32-bit blitter 0x6b15f0 (slot 1 of its class; the classes are the vtables from 0x70a18c on) blends each channel the same way and keeps the destination's alpha byte (0xff000000), so the text bitmap never carries coverage in its alpha; the texture format index [0x8bd554] (32-byte records at 0x8bd558 filled by the format enumeration 0x572f70 from the table 0x7015f8: 0 = 5-6-5, 1 = 1-5-5-5, 2 = 4-4-4-4, 3 = 8-8-8-8) is 2 or 3 by option bit 0x400000 of [0x7a1a8c] (0x44e1eb-0x44e21f, 0x58da40; always 3 when [0x8bd524] is 4), so the 5-5-5 blitter read above is not the one a default run uses; the text control is a sprite object: its sprite record at control +0x54 (built by 0x588d70) has the colour at record +0x24 (control +0x78, default 0xffffffff), the flags at +0x10 (control +0x64, 0x30000) and the scale at +0x2c (control +0x80, 1.0), and its bitmap (control +0x9c) is split into texture pages by 0x5889b0; the sprite draw that submits such records is 0x58a010 (a grid of pre-transformed quads, FVF 0x1c4, one diffuse colour per quad read from record +0x24 at 0x58a019, state word 0x400 = alpha test enabled, plus the fog bit 0x100000 of the page flags, through 0x565f90 and the state applier 0x567620), so the control colour is the quad's diffuse colour and no second pass or offset exists there either", "the blend and texture-stage state the text quads are drawn with (what the state words and page flags 0x5180200 select through the setters 0x567a70 and 0x567620: alpha reference table 0x7012d8, blend factors, colour and alpha operation) and the 4444 and 8888 blitters' alpha handling, to tell how grey coverage with alpha 0 becomes the capture's soft edges and whether the capture's apparent shadow is a render-state effect (UI-037)"),
		("UI-008", "text buttons on purple_button art (a texture name of the Mac build: tp.exe holds no 'purple' string, so which art the PC front-end buttons use is unread): each half is one end cap, drawn with its mirror image; upper half normal, lower half focused/pressed", "the PC front-end button drawer and its art names (not found by string; look for the models the front-end tables name), or a capture of the original front-end buttons"),
		("UI-013", "the confirm dialog follows table 0x7583e8, the game-mode screen the name dialog 0x753f50 and the load screen the load dialog 0x7523f0, whose rows show the park's name and, right-aligned, the save file's local date and time as 0x49ec80 formats them (UITEXT 0x1c0 with day, month and year, then \" %02d:%02d\"; shipped parks and the sandbox have no file time and show none); the lobby's and the park's pause menus lay out their lines as 0x48c150 → 0x492f60 does (text width + 1 and height + 5 pixels on the canvas, centred, from top 10, 5 units apart), but the height follows OpenTPW's menu font tier ([EXT:ui-font-tier-by-scale]); the park pause menu's online variant is read and built (0x48c36c-0x48c4af: the first line at top 10 and each next 5 below the previous one's bottom, or top 0 and gap 0 while the net-session object's field +0x60, read by 0x5b6450, is non-zero; the field is cleared at creation (0x5b51a7), by every login reply other than 0x3c (0x5b6375-0x5b63dd, which store the status 0x4b, 0x4c, 0x4d, 0x4e or else 0x37 at +0x68), by the login teardown 0x5b6510 (0x5b6588) and by the other session resets (0x5b595f, 0x5b5e7d, 0x5b7a84, 0x5b7d6a, 0x5b7f0b); every store but one writes 0, and set to 1 only by the login reply 0x3c, 'ONLINE LOGIN: Authorization OK' (0x5b6303-0x5b6363, the handler 0x5b62e0 of the connect 0x5b5d10's reply callback 0x5b5ce0), so it is the original's logged-in state and OpenTPW maps it to the authenticated session the park HUD samples on opening (HudHost.IsLoggedIn); the measure 0x4929f0 is read and matched (it lays the text out in a box through 0x6ae1c0 and returns the block box, the widest line by lines times line height, which is OpenTPW's text layout box; with its wrap flag clear the box is 0x4000 wide, so nothing wraps); the focused line's hover ramp is built (0x48b2a0 sets the ramp slot to +1 on message 0x10001 and -1 on 0x10002, 0x48b220 steps it on every message 0x1e, eight frames at the 60 Hz reference, [EXT:frame-driven-at-60hz], from grey 0x21 in steps of 0x20 to white; the ramp is driven by OpenTPW's focus, [EXT:pause-menu-hover-focus])", "OpenTPW's menu font tier"),
		("UI-018", "the lobby draws the engine sky's cloud layer (sky.tga, coloured by the eased island colour) over the fog-coloured clear, but not the scene's own fog (50 to 300 units: OpenTPW's world shaders keep their shared fog range, UI-107); while the globe is up the lobby's flyers and island clips keep stepping (the original's per-frame lobby update 0x5d5c50 has no globe branch and the main state stays 2, 0x54e6c7) but the island effects (lightning, thunder, rain, the nearest-island sky target) do not, where the islands component 0x5e0470 probably runs before the globe component sets the sky target and no rain each frame; whether the lobby scene is drawn then is not traced; the enter sequence is built (the camera turns to the island angle + π, the gate plays M1, the camera zooms under the black fade and the park starts below radius 8, 0x5e0490 states 1 and 2; an early leave's gate M2 close, 0x5e1350, is not reachable from the front end here); the key-unlock sequence is not traced", "the lobby's own fog and the sky flags that enable the engine sky's draw (0x576a00), the registration order of the lobby's subsystems while the globe is up and whether the scene is drawn then, the key-award animation's code"),
		("UI-024", "the object windows (tables 0x755150, 0x755908, 0x755e80) draw their controls at the table rectangles and, for a shop or sideshow, the customer satisfaction gauge from the object's visit history (0x4e1e30), but the preview is OpenTPW's orthographic icon ([EXT:preview-icon-cpu-projection]); the local happiness gauge counts the guests on park cells at the object's anchor cell where 0x4cd880 walks the thing lists of the cells around the thing's own cell; the build window fits the preview size to translated names and prices", "the thing cell byte pair (+5, +7) an object keeps and whether it is the placement anchor"),
		("UI-025", "the message tube retains the host capacity of five and immediate generic oldest-item eviction; the traced tube scans ten free slots independently of the advisor queue; challenge progress refreshes tagged rows at capacity, while new progress/terminal rows refuse full occupancy; terminal instances survive reading/closing, expire unread after 30 unscaled seconds, and retain hidden slots for 500 ms after expiry/deletion unless generic eviction releases them first; cross-tag replacement is synchronous; generic messages still leave on open; tube state is not saved; only offers carry actions and their original expiry/removal remains unwired; the tube art remains an extension", "generic capacity/eviction, persistence, original offer removal, full timer queue/focus/modal integration and other action-bearing sources; visual validation and UI particles (PTCL-908)"),
		("UI-026", "build icons: the preview model (P<name>.MD2, else the main model) is drawn depth tested in its own image ([EXT:preview-icon-cpu-projection]) with the original's placement, camera and face test: the fit and footprint terms of 0x4689f0, the matrix 0x468e50 rebuilds each frame (the yaw and the -π/4 tilt through the sine table, the offsets, x scaled by 0.75 and depth by 0.1), the instance's own view diag(1, -1, 1, 1) (0x45bd30, 0x57a260, used for model flag 0x200 by 0x57a750), the viewport mapping with depth × 0.1 (0x579690 mode 2), the clockwise-only face test (0x581320) and LESSEQUAL depth (0x567620, 0x57360f), its turn of 0.0004 rad a millisecond running on across selections (0x46908a, 0x468e2f), and animation 5 started on each new preview (0x4732a0: <model>m1, else <model>m, looping); but the original lights the preview's vertices in its 3D object pipeline (0x57aa10) and OpenTPW draws them unlit; the selected item's footprint grid (8×8 cells coloured by cell type in control 0x1eb, 0x4ab1b0, record 0x754d50) is built (BuyFootprint), with the 1-pixel edges of its cell rectangles not traced; the object windows' previews keep a 30° tilt and 0.8 rad/s; sign faces use the object's rendered sign textures (ObjectSigns)", "the light set the 3D pipeline gives an instance drawn with its own view (0x57aa10 with the instance's second matrix slot +0x50, which 0x45bd30 does not write) and the pixel edges of the footprint cells"),
		("UI-031", "exactly Ctrl at the placing click keeps the build tool armed (0x5253b8) and at the last click of a ride's queue re-arms it, the tool's angle returns to 0 when it is left (0x52f3b6); the coaster and water-track tools, whose original sub-modes are not traced, end the build tool whatever the modifier; the Ctrl word 0xC at 0x5259e2/0x5259f4 is Ctrl alone (the modifier builder 0x46b420: Shift 3, Ctrl 0xC, Alt 0x30) and a placement that 0x52fab0 reports as entrance-bearing (the sub-record flag +0x40) takes the tail 0x5259ae: the queue re-evaluation 0x4de1f0, the words 0x763ac0 and 0x763ac4 back to 0x80, then the map cell record +0x29c (the cell's type word, +8 of the 0x44-byte record at +0x294) of the queue's start cell that 0x52a050 gave decides at 0x5259cf: type 1 (a path cell) ends the tool through 0x52f200(0, 0) whatever the modifier, and then, as for any other start cell, exactly Ctrl keeps the angle (0x525a06) and any other word runs 0x52f1b0(0, 0), which resets it, the mode having been set to the queue tool 3 by 0x52f580 before; the coaster sub-mode (0x52faf0 = 3) takes the same tail and skips only the kart and water station line, so the tail itself enters the queue tool for a coaster as well, and the coaster's track tool (mode 0x15, 0x4474d0) is not entered anywhere in 0x524960; which OpenTPW placements end at 0x5259cf is not mapped; Level.PlaceObject owns purchase/guest linkage and its removal handler owns scrap credits", "where the original's coaster placement enters its track tool, if it does (OpenTPW enters it at the placement; the callers of the tool builder 0x46c580 and of 0x4988c0 are not traced), and which of OpenTPW's placements have a path cell as the queue's start"),
		("UI-034", "a fully opaque texture on a transparent (flag 0x2) model slot keys out black with a soft edge: transparent up to channel 6, opaque from 48, alpha ramped and colour un-premultiplied between (only ipan in the lobby f_lobbutbg panel); the texture state routine 0x567c10 sets an alpha test, an alpha reference and blend factors from the record flag bits (mask 0x556), but that its record flag 0x2 is the slot's flag 0x2 is not shown", "the original's render state for flagged texture slots (whether the record flag in 0x567c10 is the slot flag, and the colour-key handling of an opaque texture)"),
		("UI-037", "option bar label colour (16,16,48), no drop shadow; the original's options labels (0x4a43b0) and slider labels (0x4a4490) are text controls given the colour (0,0,0,255) (0x4a441e, 0x4a44fe) and font slot 6 ([0x7537b4]) and drawn once without a shadow (0x48f830); the control's colour (0,0,0,255) is stored as ARGB at control +0x78 (0x48fd07-0x48fd91), which is the colour at +0x24 of its sprite record, and the sprite draw 0x58a010 reads it as the diffuse colour of the text quads (0x58a019); how that diffuse colour combines with the grey, alpha-0 glyph bitmap on screen (texture-stage and blend state) is not read, so the capture's near-black is kept", "the blend and texture-stage state of the text quads (see UI-007): whether black diffuse over white-coverage texels gives (0,0,0) or the capture's (16,16,48)"),
		("UI-041", "Load Park takes no game type from the loaded park: the original derives GameType from flag bits 0x2000000/0x1000000 of 0x7a1a8c (0x550ca0), set by a front-end toggle (0x4bbf63), and the Mac saves none with a park", "whether a park file of the PC build can carry the game type (not traced)"),
		("UI-042", "the camera button's slide-out panel (table 0x751720) slides in and out as the arm drawer 0x4a14f0 does (ten 20 ms steps, cat_ui 0x1C and 0xC2, help 0x131), but its slide ends at the table rectangle where the original's positions come from the HUD arm window ([0x7cb2b8], its child 0x21 found at 0x4a1b35) and the arm: the arithmetic of 0x4a1613-0x4a1650 starts the panel at the arm's left less the HUD window rectangle's width and 50, centres it on the arm and puts its top 50 units above the HUD window's top (read from the instructions, medium confidence; the end position is not resolved); the camcorder button arms the C-key walk ([EXT:camcorder-first-person]) where the original's button 99 enters the camcorder at once (0x498ad0 → 0x481a10), and the walk's movement and look controls are not traced (the original's eye is terrain + 5 units, 0x42b1c0); the postcard window (table 0x7540d8) keeps its photo frame empty and its preview and address book buttons disabled (the 640×240 camcorder photo 0x4a9280, the preview redraw 0x4a84c0 and the address book 0x4a8140 are not ported); the original has no view-cycle button, so OpenTPW has none (0x751720 holds only the two buttons; no window control changes the zoom or yaw, and the locate jumps 0x42aab0 pass null zoom and yaw)", "the HUD window's rectangle; the walk's key bindings (action table 0x787c14) and the time unit of its turn step; the photo, its preview and the address book"),
		("UI-047", "coaster HUD cost now distinguishes Build/Loop/Move tool mode 3 from other panel edits in mode 8; only an active height drag exposes mode-8 cost, matching 0x447990 and the 0x441A00 bit lifecycle. Cost arithmetic and spending are unchanged", "host panel selection still substitutes for the original mode-object stack, missing-panel fallback and the gate's mode type 4 are not qualified (no mode-object class returns 4: the vtables 0x6fe980-0x6fead0 return 7, 3, 1, 5, 6, 8 and 9); a button click during a height drag ends it without the commit where the original's 0x446fa0 calls the handler's second action 0x441a00 at 0x447032 (the cost is hidden afterwards either way)"),
		("UI-051", "the ticket counter is the park's available tickets, where the original shows the player's earned tickets less the spent count (0x5af5d0, called by the HUD's counter handler 0x4a0fb0 at 0x4a10cd: the four global flags counted once, the six local bytes of every park and the two secret flags, so a global ticket that moves between parks (0x5af940) never changes it, and a park here counts the global tickets in its own set, a moved one in both parks' sets), because OpenTPW's park keeps its own spent count and never moves the player ledger's, where the original's purchase check 0x4d4ad0 calls 0x5af740, which adds the cost to the player's spent count (+0x1c) when 0x5b1930 passes; the key counter is the ledger's (0x5af680, matched)", "routing the park's ticket purchases into the player ledger (a design decision: the ledger is optional and absent in the sandbox and Instant Action)"),
		("UI-060", "finance retains the eight series colours/order, selection masks, default bank balance, zero-inclusive scale, flat baseline, fractional series coordinates and hollow 3 x 3 pixel marks below 144 samples. Finance and park information share the opaque black backdrop, dark-green grid (0,100,0), green axes/step labels (0,200,0), plot (4,4,width-20,height-20), ten horizontal divisions and twelve labeled vertical spans for 12/36/144 samples (0x4806a0, 0x47fb50, 0x47fcd0); grid coordinates accumulate stored floats and truncate, primitive lengths are pixel counts, and the negative-minimum zero axis omits the bottom branch's extra pixel (0x47fc50). Empty histories and selections keep the backdrop. Signed 128-bit axis arithmetic for long financial values, background-only tiny/unsupported host controls and nonfinite-frame rejection are host safety adaptations", "original display-mode calibration of the retained two-canvas-unit pixel adapter; financial sample-to-month correspondence and stretching of available months; font, palette, raster and composited-output fidelity; a rendered composition of the graphs"),
		("UI-064", "the research knob now keeps raw0..1023, completed-click steps of one, press-relative saved-rectangle drags, release normalization, staffing refresh, workload cameo states and the clipped capacity gauge from static evidence; raw-zero startup retains the host-normalized bottom634", "whether native post-construction startup normalizes the authored ball top399 when the initial SetPos leaves raw0 unchanged"),
		("UI-082", "the hire figure now uses the traced inner rectangle, integer feet (626,362) and nominal 2.4 canvas units per reference pixel; native delayed FRAME/start/close/invalid-selection phase, global screen rotation, depth and exact viewport/raster parity remain qualified; the employed-tab figure deliberately shares the hire-box layout as EXT:staff-employee-view, not native applicant sourcing", "native scheduler and selection/close epoch parity, global rotation/depth and private real-data viewport/raster comparison"),
		("UI-086", "paths, queues and unowned land retain the native class 10..12 records; default live placed-object fills now read the exact current economy binding's Repair (PC object +0x44, SaveAttraction.StateOfRepair), round to stored float, truncate, mask the low byte and use the native integer 16.16 ramp (248,0,0 at 0; 248,200,0 at 50; 48,252,0 at 100; alpha 255, 0x5f09a0). Absent, read-only, mismatched or malformed state retains the old magenta fallback. Native cell-class/track priority, neighbour outlines, footprints and item dots remain incomplete; independent host excitement, thought and happiness overlays keep their existing precedence rather than native value-mode dispatch", "native value modes 2/3 (excitement 0x4e0860 and satisfaction 0x4e1e30), their controls and land modes (2444..2447, 2455..2457), exact cell-class/track priority (0x5f2050, 0x5f2fd0), open-status neighbour outlines/style 8 (0x5f2a94), item dots and footprints (0x5f44d0), and real-data/native rendered comparison; default repair semantics alone do not establish pixel equivalence"),
		("UI-091", "staff radios use independently persisted and validated role chains (+0x210), with explicit whole-role fallback for malformed original chains and read-only compatibility projection for older own saves; visitor radios project live guests onto the ThingPool used chain, with an explicit ascending-ID fallback only for pool-free fixtures; visitor position failure still clears the selection, while staff identity survives unavailable coordinates; camera follow lacks the original per-frame matrix blend of 0x42b1c0 (weight (1000 - dt) x 0.0005 of the previous frame, dt clamped to 1..1000 ms); patrol rectangles (0x536100) and panel sliding remain unimplemented", "camera smoothing and retained visitor position-loss behavior; patrol presentation and slide geometry; exact-head C# validation and real-data visual comparison"),
		("UI-092", "the per-employee window uses ThingPool order, captured-target title rename and position-independent locator identity; its portrait observes current world output at yaw zero, with the existing role/variant elapsed hire-loop fallback when unavailable, and employee-only nominal 2.4 geometry at integer feet (526,476) from its inherited inner rectangle; control +0xE0 is UI depth, not animation phase", "independent-clone VM timing/state/flag history, native source-loss/refresh lifecycle, rotation/depth/occlusion and exact viewport/raster parity remain unimplemented or unverified"),
		("UI-094", "the ride view retains the camera-car/prototype eye and shared OriginalProjection; static now resets to 300 ms on an observed Boolean ride/terrain-eye edge, with positivity latched before elapsed-time subtraction (0x54faf7, 0x54fb20); host adaptations remain for single-sample monotonic timing, frame eligibility/initialization, the free-walk mapping, and the unchanged procedural noise", "native frame-gate/session lifecycle and mask bit 0x10; native noise sequence coupling and invisible window; seat/fallback axes and crowd target source; exact-head C# and real-data visual validation"),
		("UI-095", "leaving the ride view restores its prior camera instance, including the host terrain walk, and re-centres the host park camera on the object under its target with the original's test (0x42a340: a placed object whose type has CannotRide 0) and look direction (0x42a1d0: the link byte (+0xd) of the object's map cell, a 0x44-byte record at *0x7cf6ec + 0x294, masked with 0x55); the original's park camera is its own pose (yaw, height and smoothing in 0x42b1c0) that OpenTPW's host camera does not reproduce; the link byte is set whole by 0x5227e0 and cleared by bits by 0x5227f0 (called from 0x524960, 0x528a70, 0x52a050, 0x52a970, 0x52b400, 0x52ba50, 0x52fc80, 0x532fc0, 0x536490, 0x5367a0, 0x539670, 0x53af00, 0x53b280 and 0x53bb20; the writes of 0x524960 itself, at 0x524f1e, 0x5250ef and 0x525717, are on the second layer's cells of 0x28 bytes (the station line's flow link), never on an object's map cell) and reset by the cell reset 0x536490, and which of the other writers give a ride's cell its bits is not traced (OpenTPW's cell map keeps link bytes for path, queue and track cells only, so the yaw rule fires for none of the placed objects)", "which of the cell-link writers set the bits of a placed ride's cell, and the park camera's own pose"),
